HTML = '<!DOCTYPE html>\n<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>JobRadar v2 · Career Intelligence</title><style>\n:root{--blue:#1646a0;--bg:#f3f6fc;--ink:#20304a;--border:#d9e1ee;--muted:#63728c;--light:#f7f9ff}\n*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;background:var(--bg);color:var(--ink);margin:0}\nmain{max-width:1720px;margin:auto;padding:25px 30px}h1{font-size:27px;margin:0 0 5px;color:var(--blue);letter-spacing:-.5px}\nh2{font-size:14px;margin:0}p{margin:7px 0;line-height:1.55}.desc{color:var(--muted);font-size:13px}\n.toolbar,.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}\n.stats{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.stat{background:white;padding:14px 18px;border:1px solid var(--border);border-radius:12px;min-width:148px}.stat strong{display:block;font-size:25px;color:var(--blue)}.stat span{font-size:11px;color:var(--muted)}\ninput,select,button{font:inherit;font-size:13px;border-radius:7px;border:1px solid #cad5e7;padding:9px 11px;background:white;color:var(--ink)}input[type=search]{width:min(430px,100%)}button{cursor:pointer}button:hover{border-color:#5179bb;background:#eff5ff}button.primary{background:var(--blue);color:white;border-color:var(--blue)}.switch{display:flex;gap:6px;align-items:center;font-size:13px}input[type=checkbox]{width:auto}\n.surface{background:#fff;border:1px solid var(--border);border-radius:12px;overflow:hidden;box-shadow:0 2px 11px #1933560d}.tablewrap{overflow:auto;max-height:72vh}table{border-collapse:separate;border-spacing:0;width:100%;font-size:12.5px}th{white-space:nowrap;position:sticky;top:0;z-index:3;background:#e8eef9;border-bottom:1px solid var(--border);padding:8px 8px;text-align:left;color:#253c65}td{padding:10px 8px;border-bottom:1px solid #e6eaf2;vertical-align:top;max-width:260px;overflow-wrap:anywhere;line-height:1.42}tbody tr:hover{background:#f8faff}th .head{display:flex;gap:5px;align-items:center}.colname{font-weight:700;cursor:pointer;user-select:none}.fbtn{padding:2px 4px;border-radius:4px;background:transparent;border:0;color:#667d9f;font-size:11px}.fbtn.active{color:#fff;background:var(--blue)}.muted{color:var(--muted)}.badge{display:inline-block;background:#edf2ff;color:#24478f;border-radius:20px;padding:4px 8px;white-space:nowrap;font-size:11px}.badge.old{background:#f0f2f6;color:#536175}.badge.skipped{background:#fff1f1;color:#963934}a{color:#1646a0;text-decoration:none}a:hover{text-decoration:underline}.pop{position:fixed;z-index:40;background:white;border:1px solid #cdd7e7;box-shadow:0 16px 38px #1c376033;border-radius:10px;width:260px;max-height:340px;padding:12px;display:none}.pop.active{display:block}.p-options{max-height:210px;overflow:auto;margin:10px 0}.p-row{display:flex;gap:8px;align-items:center;padding:4px 0;font-size:12px;cursor:pointer}.p-row input{margin:0}.pop-actions{display:flex;gap:5px;justify-content:space-between}small{color:var(--muted)}.pager{display:flex;align-items:center;gap:9px;padding:12px;justify-content:space-between;border-top:1px solid var(--border);font-size:12px}.hidden{display:none!important}.notes{margin:14px 0 24px;font-size:12px;color:var(--muted);line-height:1.6}.warning{background:#fffaf0;border:1px solid #ecdda9;border-radius:10px;padding:10px 13px;font-size:12px}.mono{font:11px Menlo,monospace}\n@media(max-width:650px){main{padding:14px}h1{font-size:23px}td{min-width:110px} .stats{gap:6px}.stat{min-width:110px;padding:10px}}\n</style></head><body><main>\n<header><h1>JobRadar <span style="font-weight:400;color:#7993bb">/ v2.0</span></h1><p class="desc">Career Intelligence · manuel tarama · yalnızca hedef roller · tamamen yerel değerlendirme</p></header>\n<div class="stats"><div class="stat"><strong id="nAll">0</strong><span>Toplam uygun ilan</span></div><div class="stat"><strong id="nVisible">0</strong><span>Filtre sonrası</span></div><div class="stat"><strong id="nNew">0</strong><span>Yeni tespit edilen</span></div><div class="stat"><strong id="nTarget">0</strong><span>Hedef ülke</span></div></div>\n<div class="warning"><b>Durum açıklaması:</b> “İlk tarama” (BASELINE) ilk aramada zaten veri kaynaklarında bulunan, henüz değerlendirilmemiş ilan demektir; başvurulduğu veya reddedildiği anlamına gelmez. “Yeni tespit” ise bir sonraki taramada ilk kez görülmüş kayıttır. Kaynak tarihi, işverenin gerçek ilk ilan tarihi olmayabilir.</div>\n<div class="toolbar"><input id="search" type="search" placeholder="Şirket, pozisyon, ülke veya şehir ara…" aria-label="Genel arama"/><label class="switch"><input type="checkbox" id="onlyNew"/> Yalnızca yeni tespit</label><label class="switch"><input type="checkbox" id="diag"/> Teknik kolonları göster</label><button id="reset">Filtreleri sıfırla</button><button id="export">CSV dışa aktar</button></div>\n<div class="controls"><span class="desc">Sıralamak için kolon adına; çoklu seçim için <b>▾</b> simgesine tıkla. Kolon filtreleri birbirinden bağımsızdır.</span></div>\n<div class="surface"><div class="tablewrap"><table><thead id="heads"></thead><tbody id="body"></tbody></table></div><div class="pager"><span id="totalRows">—</span><div><button id="prev">← Önceki</button><span id="pageCount"></span><button id="next">Sonraki →</button></div></div></div>\n<div class="notes">* <b>İlan yaşı</b> kaynakta yayımlanma tarihi varsa takvim günü farkıdır; gerçekte kaç gündür açık olduğunu garanti etmez. Boş: tarih güvenilir biçimde sağlanmadı. <b>Yerel ilk görüldü</b> teknik kolonunu isteğe bağlı açabilirsin. Remote yazması Türkiye\'den çalışılabileceğini kanıtlamaz. Uygulama otomatik başvuru yapmaz. Jobicy ve Himalayas için kaynak bağlantısını koru, işverenin resmi ilanıyla ayrıca doğrula.</div>\n</main><div id="popover" class="pop"><b id="popTitle"></b><p><input type="search" id="popSearch" placeholder="Değer ara" style="width:100%"/></p><div id="popChoices" class="p-options"></div><div class="pop-actions"><button id="popAll">Tümü</button><button id="popNone">Hiçbiri</button><button class="primary" id="popClose">Uygula</button></div></div>\n<script type="application/json" id="data">__DATA__</script>\n<script>\n\'use strict\';\nconst jobs=JSON.parse(document.getElementById(\'data\').textContent);\nconst cols=[{k:\'company\',l:\'Şirket\'},{k:\'title\',l:\'Pozisyon\'},{k:\'city\',l:\'Şehir / eyalet\'},{k:\'country\',l:\'Ülke\'},{k:\'mode\',l:\'Çalışma\'},{k:\'status\',l:\'Durum\'},{k:\'source\',l:\'Kaynak\'},{k:\'posted\',l:\'İlan tarihi*\'},{k:\'age\',l:\'İlan yaşı*\',type:\'numeric\'},{k:\'link\',l:\'Başvuru\'},{k:\'first_seen\',l:\'Yerel ilk görüldü\',diag:true},{k:\'id\',l:\'Kayıt ID\',diag:true}];\nconst state={text:\'\',onlyNew:false,diagnostics:false,page:1,pageSize:100,sort:\'age\',dir:1,filters:{}};\nconst $=id=>document.getElementById(id);\nconst cellLabel=j=>({BASELINE:\'İlk tarama\',DISCOVERED:\'Yeni tespit\',EVALUATED:\'Değerlendirildi\',\'PREPARED ONLY\':\'Taslak hazır\',CLARIFY:\'Netleştir\',SKIP:\'Geç\',CLOSED:\'Kapandı\',\'SUBMITTED CONFIRMED\':\'Başvuru yapıldı\',\'PREVIOUS REJECTION\':\'Önceki ret\',\'EXPLICIT STOP REQUEST\':\'Durdur\'})[j.status]||j.status;\nfunction value(row,key){if(key===\'status\')return cellLabel(row);if(key===\'age\')return row.age===null?\'Bilinmiyor\':String(row.age);return String(row[key]??\'\');}\nfunction entries(){return jobs.filter(j=>{\n if(state.onlyNew&&j.status!==\'DISCOVERED\')return false;\n if(state.text&&!([j.company,j.title,j.city,j.country,j.mode,j.source].join(\' \').toLocaleLowerCase(\'tr\').includes(state.text)))return false;\n return Object.entries(state.filters).every(([k,vals])=>vals===null||vals.has(value(j,k)));\n }).sort((a,b)=>{let x=value(a,state.sort),y=value(b,state.sort);if(state.sort===\'age\'){x=a.age??999999;y=b.age??999999;return (x-y)*state.dir;}return x.localeCompare(y,\'tr\',{numeric:true})*state.dir;});}\nfunction render(){const visible=cols.filter(c=>!c.diag||state.diagnostics);$(\'heads\').replaceChildren();const tr=document.createElement(\'tr\');visible.forEach(c=>{\n  const th=document.createElement(\'th\'),wrap=document.createElement(\'div\'),name=document.createElement(\'span\'),f=document.createElement(\'button\');wrap.className=\'head\';name.className=\'colname\';name.textContent=c.l+(state.sort===c.k?(state.dir===1?\' ↑\':\' ↓\'):\'\');name.title=\'Bu kolona göre sırala\';name.onclick=()=>{if(state.sort===c.k)state.dir*=-1;else{state.sort=c.k;state.dir=1;}render();};f.className=\'fbtn\'+(state.filters[c.k]?\' active\':\'\');f.textContent=\'▾\';f.title=c.l+\' için çoklu filtre\';f.onclick=e=>showFilter(c.k,c.l,e.currentTarget);wrap.append(name,f);th.append(wrap);tr.append(th);\n });$(\'heads\').append(tr);\n const filtered=entries(),start=(state.page-1)*state.pageSize;let page=filtered.slice(start,start+state.pageSize);if(!page.length&&state.page>1){state.page=1;page=filtered.slice(0,state.pageSize);}\n const tbody=$(\'body\');tbody.replaceChildren();page.forEach(j=>{const tr=document.createElement(\'tr\');visible.forEach(c=>{const td=document.createElement(\'td\'),v=value(j,c.k);if(c.k===\'link\'&&/^https:\\/\\//.test(j.link)){const a=document.createElement(\'a\');a.href=j.link;a.target=\'_blank\';a.rel=\'noopener noreferrer\';a.textContent=\'İlanı aç ↗\';td.append(a);}else if(c.k===\'status\'){const tag=document.createElement(\'span\');tag.className=\'badge \'+(j.status===\'BASELINE\'?\'old\':j.status===\'SKIP\'?\'skipped\':\'\');tag.textContent=v;td.append(tag);}else{td.textContent=v;if(c.k===\'id\')td.className=\'mono\';if(c.k===\'age\'&&j.age===null)td.className=\'muted\';}tr.append(td);});tbody.append(tr);});\n $(\'nAll\').textContent=jobs.length;$(\'nNew\').textContent=jobs.filter(j=>j.status===\'DISCOVERED\').length;$(\'nTarget\').textContent=jobs.filter(j=>[\'Türkiye\',\'Suudi Arabistan\',\'Birleşik Arap Emirlikleri\',\'Katar\'].includes(j.country)).length;$(\'nVisible\').textContent=filtered.length;\n $(\'totalRows\').textContent=filtered.length+\' ilan · sayfada \'+page.length;$(\'pageCount\').textContent=state.page+\' / \'+Math.max(1,Math.ceil(filtered.length/state.pageSize));$(\'prev\').disabled=state.page<=1;$(\'next\').disabled=start+state.pageSize>=filtered.length;\n}\nlet activeKey=\'\';function showFilter(key,title,btn){activeKey=key;$(\'popTitle\').textContent=title;$(\'popSearch\').value=\'\';const p=$(\'popover\'),rect=btn.getBoundingClientRect();p.style.left=Math.min(rect.left,innerWidth-275)+\'px\';p.style.top=Math.min(rect.bottom+5,innerHeight-365)+\'px\';p.classList.add(\'active\');renderChoices();$(\'popSearch\').focus();}\nfunction renderChoices(){const opts=[...new Set(jobs.map(j=>value(j,activeKey)))].sort((a,b)=>a.localeCompare(b,\'tr\',{numeric:true}));const selected=state.filters[activeKey];const q=$(\'popSearch\').value.toLocaleLowerCase(\'tr\');const root=$(\'popChoices\');root.replaceChildren();opts.filter(v=>v.toLocaleLowerCase(\'tr\').includes(q)).forEach(v=>{const label=document.createElement(\'label\');label.className=\'p-row\';const cb=document.createElement(\'input\');cb.type=\'checkbox\';cb.checked=!selected||selected.has(v);cb.onchange=()=>{if(!state.filters[activeKey])state.filters[activeKey]=new Set(opts);if(cb.checked)state.filters[activeKey].add(v);else state.filters[activeKey].delete(v);state.page=1;};const text=document.createElement(\'span\');text.textContent=v||\'(boş)\';label.append(cb,text);root.append(label);});}\n$(\'popSearch\').oninput=renderChoices;$(\'popAll\').onclick=()=>{delete state.filters[activeKey];renderChoices();state.page=1;};$(\'popNone\').onclick=()=>{state.filters[activeKey]=new Set();renderChoices();state.page=1;};$(\'popClose\').onclick=()=>{$(\'popover\').classList.remove(\'active\');render();};document.addEventListener(\'click\',e=>{if(!$(\'popover\').contains(e.target)&&!e.target.classList.contains(\'fbtn\')){$(\'popover\').classList.remove(\'active\');}});\n$(\'search\').oninput=e=>{state.text=e.target.value.toLocaleLowerCase(\'tr\');state.page=1;render();};$(\'onlyNew\').onchange=e=>{state.onlyNew=e.target.checked;state.page=1;render();};$(\'diag\').onchange=e=>{state.diagnostics=e.target.checked;render();};$(\'reset\').onclick=()=>{state.text=\'\';state.onlyNew=false;state.filters={};state.page=1;$(\'search\').value=\'\';$(\'onlyNew\').checked=false;render();};$(\'prev\').onclick=()=>{state.page--;render();};$(\'next\').onclick=()=>{state.page++;render();};\n$(\'export\').onclick=()=>{const rows=entries(),columns=cols.filter(c=>!c.diag||state.diagnostics).filter(c=>c.k!==\'link\');const quote=x=>\'"\'+String(x??\'\').replace(/"/g,\'""\')+\'"\';const csv=\'\\ufeff\'+[columns.map(c=>quote(c.l)).join(\',\'),...rows.map(r=>columns.map(c=>quote(value(r,c.k))).join(\',\'))].join(\'\\r\\n\');const blob=new Blob([csv],{type:\'text/csv;charset=utf-8\'});const url=URL.createObjectURL(blob),a=document.createElement(\'a\');a.href=url;a.download=\'JobRadar_filtered.csv\';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);};\nrender();\n</script></body></html>'

def age(posted):
 try:
  x=datetime.fromisoformat(str(posted).replace("Z","+00:00"))
  return max(0,(datetime.now(timezone.utc).date()-x.date()).days)
 except (ValueError,TypeError):return None

def dashboard(dest=None):
 dest=Path(dest) if dest else core.ROOT/'output'/'dashboard.html'
 dest.parent.mkdir(parents=True,exist_ok=True)
 db=core.connect();rows=db.execute("SELECT id,company,title,location,countries,cities,work_mode,status,source,url,posted_at,local_first_seen FROM jobs ORDER BY local_first_seen DESC LIMIT 10000").fetchall();db.close()
 data=[]
 for raw in rows:
  j=dict(raw)
  for k in ('countries','cities'):
   try:j[k]=json.loads(j[k] or '[]')
   except (json.JSONDecodeError,TypeError):j[k]=[]
  city,country,_=parse_location(j);posted=j.get('posted_at')
  data.append(dict(id=j['id'],company=j['company'],title=j['title'],city=city or '—',country=country,mode=j['work_mode'] or 'Belirtilmemiş',status=j['status'],source=j['source'],posted=str(posted)[:10] if age(posted)!=None else '—',age=age(posted),first_seen=(j['local_first_seen'] or '')[:16],link=j['url'] if str(j.get('url') or '').startswith('https://') else ''))
 safe=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
 dest.write_text(HTML.replace('__DATA__',safe),encoding='utf-8')
 print('Dashboard:',dest);return dest
